/** Loose service definition shape used to store heterogeneous services in the registry. */
type RegisteredServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
/** Loose runtime instance shape returned from registration and discovery helpers. */
type RegisteredServiceInstance = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;

/**
 * Optional handler overrides that can be supplied when registering a service.
 *
 * A service definition already carries inline handlers, but callers can override or supply a
 * handler (and query `preload`) implementation at registration time — for example to swap in a
