export type ServiceHandlers<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries?: {
    [TKey in keyof TQueries]?: Partial<Pick<TQueries[TKey], 'handler' | 'preload'>>;
  };
  commands?: {
    [TKey in keyof TCommands]?: Partial<Pick<TCommands[TKey], 'handler'>>;
  };
};

/** Compact summary of a registered service, returned by {@link listServices}. */
export type ServiceSummary = {
  id: string;
  description?: string;
  queryNames: string[];
  commandNames: string[];
};

/** Metadata describing a single query or command operation. */
export type OperationDescriptor = {
  name: string;
  description?: string;
};

/** Detailed descriptor of a registered service, returned by {@link describeService}. */
export type ServiceDescriptor = {
  id: string;
  description?: string;
  queries: OperationDescriptor[];
  commands: OperationDescriptor[];
};

/** One entry in the global registry, pairing a definition with its live runtime instance. */
type ServiceRegistration = {
  definition: RegisteredServiceDefinition;
  instance: RegisteredServiceInstance;
};

