 *
 * Unlike the singleton cache in `service-runtime.ts`, this registry is the authoritative catalog of
 * services the server knows about. It powers discovery (`listServices`, `describeService`) and
 * static file generation (`buildStaticFiles`).
 */
const registry = new Map<string, ServiceRegistration>();

/**
 * Applies optional handler overrides on top of a service definition.
 *
 * The original definition is never mutated; a shallow copy is produced with the overridden
 * `handler`/`preload` implementations merged into the matching query and command objects.
 */
function applyHandlers<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  handlers?: ServiceHandlers<TState, TQueries, TCommands>
): ServiceDefinition<TState, TQueries, TCommands> {
  if (!handlers) {
    return definition;
  }

  const queries = { ...definition.queries } as TQueries;
  for (const [name, override] of Object.entries(handlers.queries ?? {})) {
    if (override && name in queries) {
      queries[name as keyof TQueries] = {
        ...queries[name as keyof TQueries],
        ...override,
      };
    }
  }

  const commands = { ...definition.commands } as TCommands;
  for (const [name, override] of Object.entries(handlers.commands ?? {})) {
    if (override && name in commands) {
      commands[name as keyof TCommands] = {
        ...commands[name as keyof TCommands],
        ...override,
      };
    }
  }

  return { ...definition, queries, commands };
}

/**
 * Registers a service in the global registry and returns its runtime instance.
 *
 * Optional handler overrides are merged onto the definition before the instance is created. A
 * service id may only be registered once; re-registering the same id throws.
 */
export function registerService<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  handlers?: ServiceHandlers<TState, TQueries, TCommands>
): ServiceInstance<TState, TQueries, TCommands> {
  if (registry.has(definition.id)) {
    throw new OpenServiceDuplicateRegistrationError({ serviceId: definition.id });
  }

  const resolvedDefinition = applyHandlers(definition, handlers);
  const instance = createService(resolvedDefinition);

  registry.set(definition.id, {
    definition: resolvedDefinition as unknown as RegisteredServiceDefinition,
    instance: instance as unknown as RegisteredServiceInstance,
  });

  return instance;
}

/** Returns the registration for an id, or throws a structured not-found error. */
function requireRegistration(id: string): ServiceRegistration {
  const registration = registry.get(id);

  if (!registration) {
    throw new OpenServiceNotFoundError({
      serviceId: id,
      availableServiceIds: [...registry.keys()],
    });
  }

  return registration;
}

/**
 * Resolves a registered service instance by its id.
 *
 * Rejects with {@link OpenServiceNotFoundError} when no service is registered under the id.
 */
export async function getService(id: string): Promise<RegisteredServiceInstance> {
  return requireRegistration(id).instance;
}

/** Returns every registered service instance as a synchronous snapshot array. */
export function getRegisteredServices(): RegisteredServiceInstance[] {
  return [...registry.values()].map((registration) => registration.instance);
}

/** Resolves compact summaries for every registered service. */
export async function listServices(): Promise<ServiceSummary[]> {
  return [...registry.values()].map(({ definition }) => ({
    id: definition.id,
    description: definition.description,
    queryNames: Object.keys(definition.queries),
    commandNames: Object.keys(definition.commands),
  }));
}

/** Builds descriptors for the queries or commands of a service. */
function describeOperations(
  operations: Record<string, { description?: string }>
): OperationDescriptor[] {
  return Object.entries(operations).map(([name, operation]) => ({
    name,
    description: operation.description,
  }));
}

/**
 * Resolves a detailed descriptor for a single service, including its queries and commands.
 *
 * Rejects with {@link OpenServiceNotFoundError} when no service is registered under the id.
 */
export async function describeService(id: string): Promise<ServiceDescriptor> {
  const { definition } = requireRegistration(id);

  return {
    id: definition.id,
    description: definition.description,
    queries: describeOperations(definition.queries),
    commands: describeOperations(definition.commands),
  };
}

/** Removes every service from the global registry. */
export function clearRegistry(): void {
  registry.clear();
}

